try {
  const items = $input.all();
  let newsList = '';

  for (let i = 0; i < items.length; i++) {
    const title = items[i].json.title || 'Без заголовка';
    const link = items[i].json.link || '';
    newsList += `${i + 1}. ${title}\nСсылка: ${link}\n\n`;
  }

  return [{ json: { combinedNews: newsList } }];

} catch (error) {
  return [{ json: { 
    combinedNews: 'Ошибка при обработке новостей', 
    error: error.message 
  } }];
}

