try {
const items = $input.all();

let newsDigest = '';
let priceData = '';

for (const item of items) {
  // Новостной дайджест (из Code in JavaScript1)
  if (item.json.cleanText) {
    newsDigest = item.json.cleanText;
  }

  // Детальные данные по ценам (из HTTP Request2)
  if (item.json.summary) {
    const s = item.json.summary;
    priceData = `Текущая цена: $${s.current_price}
Средняя за 6 мес: $${s.avg_price_6m}
Минимум: $${s.min_price} (${s.min_date})
Максимум: $${s.max_price} (${s.max_date})
Изменение за месяц: ${s.change_1m_pct}%
Средняя за последний месяц: $${s.avg_last_month}
Средняя за предыдущий месяц: $${s.avg_prev_month}
Тренд: ${s.trend}
Волатильность (30 дней): ${s.volatility_30d}%
Волатильность (6 мес): ${s.volatility_6m}%
Период: ${s.period}
Источник: ${s.source}

Дневные данные за последние 30 дней:
${JSON.stringify(item.json.daily_prices_last_30d)}`;
  }
}

// Дебаг — чтобы видеть что пришло
const debugInfo = `[DEBUG] Items: ${items.length}, News: ${newsDigest.length > 0 ? 'YES' : 'NO'}, Prices: ${priceData.length > 0 ? 'YES' : 'NO'}`;

return [{
  json: {
    combinedPrompt: `БЛОК 1 — НОВОСТИ:\n${newsDigest}\n\nБЛОК 2 — ДАННЫЕ ПО ЦЕНАМ:\n${priceData}`,
    debug: debugInfo
  }
}];

} catch (error) {
  return [{ json: { 
    combinedNews: 'Ошибка при обработке новостей', 
    error: error.message 
  } }];
}

try {
const text = $input.first().json.output || '';

const clean = text
  .replace(/\*\*/g, '')
  .replace(/\*/g, '')
  .replace(/_/g, ' ')
  .replace(/`/g, '');

return [{ json: { cleanText: clean } }];

} catch (error) {
  return [{ json: { 
    text: 'Ошибка при разбивке текста на чанки', 
    error: error.message 
  } }];
}

try {
const text = $input.first().json.cleanText;
const maxLen = 4000;
const chunks = [];

for (let i = 0; i < text.length; i += maxLen) {
  chunks.push({ json: { text: text.substring(i, i + maxLen) } });
}

return chunks;

} catch (error) {
  return [{ json: { 
    text: 'Ошибка при разбивке текста на малые текста', 
    error: error.message 
  } }];
}

const now = new Date();
const timestamp = now.toISOString().replace('T', ' ').substring(0, 19);

return [{
  json: {
    timestamp: timestamp,
    status: 'SUCCESS',
    news_count: '5',
    brent_price: '',
    error_message: '',
    execution_id: $execution.id
  }
}];
